model_safe_stan:
/*
 * BUGS Volume 3, funshapes, parallelogram
 * http://www.openbugs.net/Examples/Funshapes.html
 */
parameters {
  real<lower=0, upper=1> x;
  real<lower=0, upper=1> y_raw;
}
transformed parameters {
  real<lower=-1, upper=1> y;
  y = y_raw - x;
}
model {
  x ~ uniform(0, 1);
  y_raw ~ uniform(0, 1);
}
